            await _semaphore.WaitAsync(ct).ConfigureAwait(false);
            try
            {
                Interlocked.Increment(ref _step);
                var data = inputData ?? Array.Empty<double>();
                var sw = Stopwatch.StartNew();

                // Compute primary statistics
                double mean = data.Length > 0 ? data.Average() : 0.0;
                double variance = data.Length > 1
                    ? data.Select(x => (x - mean) * (x - mean)).Average()
                    : 0.0;
                double norm = Math.Sqrt(data.Select(x => x * x).Sum());
                double scale = _config.LearningRate * (1.0 + 18 * 0.01);

                // Apply transformation with EWC regularization
                var transformed = data.Take(64).Select(x => x * scale).ToArray();
                double ewcPenalty = _config.EWCLambda * variance * 0.001;

                // Quantum Fisher information estimate
                double fisherNorm = norm * _config.QuantumCoherence;

                // Update metrics
